دالة هل_كامل(ن) {
    متغير مجموع = ٠
    من_أجل (ع من ١ إلى ن - ١) {
        إذا (ن % ع == ٠) {
            مجموع = مجموع + ع
        }
    }
    إذا (مجموع == ن) {
        ارجع صحيح
    } وإلا {
        ارجع خطأ
    }
}
```

